INSERT INTO `quqql19koe_ac_email_templates` VALUES (1,'no@email.com','Secret Board Games: Did you have checkout trouble?','<html>\r\n                                   <head>\r\n                                       <title>My document title</title>\r\n                                   </head>\r\n                                       <body>\r\n\r\n                                       <p> Hello {{customer.fullname}}, </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> We\'re following up with you, because we noticed that on {{cart.abandoned_date}} you attempted to purchase the following products on {{shop.name}}. </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> <table border=\"0\" cellspacing=\"5\"><caption><b>Cart Details</b></caption>\r\n                                			<tbody>\r\n                                			<tr>\r\n                                			<th></th>\r\n                                			<th>Product</th>\r\n                                			<th>Price</th>\r\n                                			<th>Quantity</th>\r\n                                			<th>Total</th>\r\n                                			</tr>\r\n                                			<tr style=\"background-color:#f4f5f4;\"><td>{{item.image}}</td><td>{{item.name}}</td><td>{{item.price}}</td><td>{{item.quantity}}</td><td>{{item.subtotal}}</td></tr>\r\n                                			<tr>\r\n                                			<td>&nbsp;</td>\r\n                                			<td>&nbsp;</td>\r\n                                			<td>&nbsp;</td>\r\n                                			<th>Cart Total:</th>\r\n                                			<td>{{cart.total}}</td>\r\n                                			</tr></tbody></table> </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> If you had any purchase troubles, could you please Contact to share them? </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> Otherwise, how about giving us another chance? Shop <a href=\"{{shop.url}}\">{{shop.name}}</a>. </p>\r\n                                       <hr></hr>\r\n                                       <p> You may <a href=\"{{cart.unsubscribe}}\">unsubscribe</a> to stop receiving these emails. </p> \r\n                                       <p> &nbsp; </p>\r\n                                       <p> <a href=\"{{shop.url}}\">{{shop.name}}</a> appreciates your business.  </p>\r\n\r\n                                   </body>\r\n                           </html>','0',1,'Hours','','Initial','Admin','no@email.com',1,'0','0','1',''),(2,'no@email.com','Secret Board Games: We want your business!','<html>\r\n                                   <head>\r\n                                       <title>My document title</title>\r\n                                   </head>\r\n                                       <body>\r\n\r\n                                       <p> Hello {{customer.fullname}}, </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> We\'re following up with you, because we noticed that on {{cart.abandoned_date}} you attempted to purchase the following products on {{shop.name}}. </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> <table border=\"0\" cellspacing=\"5\"><caption><b>Cart Details</b></caption>\r\n                                			<tbody>\r\n                                			<tr>\r\n                                			<th></th>\r\n                                			<th>Product</th>\r\n                                			<th>Price</th>\r\n                                			<th>Quantity</th>\r\n                                			<th>Total</th>\r\n                                			</tr>\r\n                                			<tr style=\"background-color:#f4f5f4;\"><td>{{item.image}}</td><td>{{item.name}}</td><td>{{item.price}}</td><td>{{item.quantity}}</td><td>{{item.subtotal}}</td></tr>\r\n                                			<tr>\r\n                                			<td>&nbsp;</td>\r\n                                			<td>&nbsp;</td>\r\n                                			<td>&nbsp;</td>\r\n                                			<th>Cart Total:</th>\r\n                                			<td>{{cart.total}}</td>\r\n                                			</tr></tbody></table> </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> If you had any purchase troubles, could you please Contact to share them? </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> Otherwise, how about giving us another chance? Shop <a href=\"{{shop.url}}\">{{shop.name}}</a>. </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> As a thank you for coming back, here\'s a single-use coupon for 5% off. You can use discount code \"{{coupon.code}}\"&nbsp;during <a href=\"{{checkout.link}}\" >checkout</a>. </p>\r\n                                       <hr></hr>\r\n                                       <p> You may <a href=\"{{cart.unsubscribe}}\">unsubscribe</a> to stop receiving these emails. </p> \r\n                                       <p> &nbsp; </p>\r\n                                       <p> <a href=\"{{shop.url}}\">{{shop.name}}</a> appreciates your business.  </p>\r\n\r\n                                   </body>\r\n                           </html>','0',1,'Days','','Interim','Admin','no@email.com',1,'5','0','1',''),(3,'no@email.com','Secret Board Games: Final Offer!','<html>\r\n                                   <head>\r\n                                       <title>My document title</title>\r\n                                   </head>\r\n                                       <body>\r\n\r\n                                       <p> Hello {{customer.fullname}}, </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> We\'re following up with you, because we noticed that on {{cart.abandoned_date}} you attempted to purchase the following products on {{shop.name}}. </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> <table border=\"0\" cellspacing=\"5\"><caption><b>Cart Details</b></caption>\r\n                                			<tbody>\r\n                                			<tr>\r\n                                			<th></th>\r\n                                			<th>Product</th>\r\n                                			<th>Price</th>\r\n                                			<th>Quantity</th>\r\n                                			<th>Total</th>\r\n                                			</tr>\r\n                                			<tr style=\"background-color:#f4f5f4;\"><td>{{item.image}}</td><td>{{item.name}}</td><td>{{item.price}}</td><td>{{item.quantity}}</td><td>{{item.subtotal}}</td></tr>\r\n                                			<tr>\r\n                                			<td>&nbsp;</td>\r\n                                			<td>&nbsp;</td>\r\n                                			<td>&nbsp;</td>\r\n                                			<th>Cart Total:</th>\r\n                                			<td>{{cart.total}}</td>\r\n                                			</tr></tbody></table> </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> If you had any purchase troubles, could you please Contact to share them? </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> Otherwise, how about giving us another chance? Shop <a href=\"{{shop.url}}\">{{shop.name}}</a>. </p>\r\n                                       <p> &nbsp; </p>\r\n                                       <p> As a thank you for coming back, here\'s a single-use coupon for 10% off. You can use discount code \"{{coupon.code}}\"&nbsp;during <a href=\"{{checkout.link}}\" >checkout</a>. </p>\r\n                                       <hr></hr>\r\n                                       <p> You may <a href=\"{{cart.unsubscribe}}\">unsubscribe</a> to stop receiving these emails. </p> \r\n                                       <p> &nbsp; </p>\r\n                                       <p> <a href=\"{{shop.url}}\">{{shop.name}}</a> appreciates your business.  </p>\r\n\r\n                                   </body>\r\n                           </html>','0',2,'Days','','Final','Admin','no@email.com',1,'10','0','1','');
