clear: both;\r\n    }\r\n    .woocommerce div.product .product_title {\r\n        padding-top: 20px;\r\n        margin-bottom: 0;\r\n    }\r\n    .footer-widgets-2 .menu > li {\r\n        width: 33%;\r\n        float: left;\r\n        padding-left: 0;\r\n        text-align: left;\r\n    }\r\n    .section-7 .conright, .section-7 .conleft {\r\n        width: 50%;\r\n    }\r\n    .conright > div {\r\n        display: none;\r\n    }\r\n    .conright > div:nth-of-type(2) {\r\n        display: block;\r\n    }\r\n    .brgmp-info .img-left, .brgmp-info .list-right {\r\n    	width: 100%\r\n    }\r\n    .title-on {\r\n        text-align: left;\r\n    }\r\n    .section-9 .btn {\r\n        font-size: 14px;\r\n    }\r\n}\r\n\r\n@media only screen and (max-width: 480px) {\r\n    .br-product-data .left-data, .br-product-data .right-data {\r\n        width: 100%;\r\n    }\r\n    .social-share a {\r\n        font-size: 10px;\r\n    }\r\n    .single #comments, .single #review_form_wrapper {\r\n        float: none;\r\n        width: 100%;\r\n    }\r\n    \r\n    div.section-1 {\r\n        display: none;    \r\n    }\r\n    \r\n    \r\n    div.section-7 .conleft,\r\n    div.section-7 .conright\r\n    {\r\n        width: auto;\r\n        float: none;\r\n    }\r\n    \r\n    div.section-7 .conright ol li {\r\n        text-align: left;\r\n    }\r\n    \r\n    .title-area {\r\n\r\n        width: auto;\r\n    }\r\n    \r\n    #text-5 {\r\n        display:none;\r\n    }\r\n    \r\n    .genesis-nav-menu .sub-menu a {\r\n        width: auto;\r\n    }\r\n    \r\n    .genesis-nav-menu .sub-menu {\r\n        margin: 0;\r\n    }\r\n    \r\n}\r\n\r\n.woocommerce a.remove{ color: grey !important;}\r\n\r\n.menu-item {margin-bottom:0px !important;}\r\n\r\n.bucksDisplay{\r\n    display: block;\r\n    border: 1px solid #000;\r\n    text-align: center;\r\n    font-size: 20px;\r\n    font-weight: bold;\r\n    padding: 10px 00;\r\n    position: relative;\r\n    background: url(/wp-content/uploads/2016/05/moneyicon.jpg) no-repeat;\r\n}\r\n\r\n/*CHECKOUT MODIFICATIONS*/\r\n#createaccount{\r\n    visibility:hidden;\r\n}\r\nlabel[for=\"createaccount\"]{\r\n    visibility:hidden;\r\n}\r\n.rateGameText{\r\n    color:#99cc00;\r\n    font-weight:bold;\r\n}\r\n.gimmeArrowsafter::after{\r\n    content: \"»\";\r\n    margin-left: 5px;\r\n    vertical-align: middle;\r\n    line-height: 0.9;\r\n}\r\n\r\n/*OLD BGPR STYLE*/\r\n#add_payment_method #payment ul.payment_methods, .woocommerce-cart #payment ul.payment_methods, .woocommerce-checkout #payment ul.payment_methods{\r\n    border-bottom: none !important;\r\n}\r\n#add_payment_method #payment, .woocommerce-cart #payment, .woocommerce-checkout #payment { background-color: #FFF !important;}\r\n#add_payment_method #payment div.payment_box, .woocommerce-cart #payment div.payment_box, .woocommerce-checkout #payment div.payment_box{ background-color: #FFF !important;}\r\n\r\n/*form inputs*/\r\n.woocommerce form .form-row input.input-text, .woocommerce form .form-row textarea{ background-color: #e9e9e9 !important; border: 1px solid #aeaeae !important; border-radius: 0px !important; color: #434343 !important;}\r\n/*payment form CC*/\r\n.simple-form .form-group{ width: 45% !important;}\r\n.simple-form .form-group .hosted-field {background-color: #e9e9e9 !important; border: 1px solid #aeaeae !important; border-radius: 0px !important; color: #434343 !important; height: 40px !important; padding: 3px !important; font-family: \"Helvetica Neue\",Helvetica,Arial,sans-serif !important;}\r\n.simple-form { border: none !important;}\r\n\r\nul.checkout_info { list-style: none;}\r\nul.checkout_info li{ height: 120px; padding: 10px; list-style: none;}\r\nul.checkout_info li h3{ color: #3fbffe;}\r\nul.checkout_info li p{ margin-left: 50px; line-height: 14px; font-size: 12px;}\r\n\r\nbody.woocommerce-checkout .woocommerce table.shop_table { width: 50% !important;}\r\nbody.woocommerce-checkout #account_password { width: 50% !important;}\r\n.tax-total.recurring-total,.recurring-totals, .cart-subtotal.recurring-total{display: none;}\";s:24:\"custom_php_field_options\";s:1:\"1\";s:14:\"cmk-custom-php\";s:48596:\"<?php\r\n\r\n//load additional header script\r\nadd_action(\'wp_enqueue_scripts\', \'_bg_add_scripts\' );\r\nfunction _bg_add_scripts() {\r\n    wp_enqueue_style(\'bg-fonts\', \'https://fonts.googleapis.com/css?family=Montserrat|Poppins\');\r\n    if ( is_single() && is_singular( \'post\' ) ) {\r\n        wp_enqueue_script(\'cm-valid\', Dynatheme::$cmk_url .\'/js/jquery.validate.min.js\', array(), \'1.1\', true );\r\n    }\r\n}\r\n//Add tracking javascript\r\n//NO LONGER USED  - HANDLED BY PLUGIN\r\nfunction add_screentracking_js() {\r\n    ?>\r\n    <script type=\'text/javascript\'> \r\n    window.__lo_site_id = 66699; \r\n    (function() { \r\n    var wa = document.createElement(\'script\'); wa.type = \'text/javascript\'; wa.async = true; \r\n    wa.src = \'https://d10lpsik1i8c69.cloudfront.net/w.js\'; \r\n    var s = document.getElementsByTagName(\'script\')[0]; s.parentNode.insertBefore(wa, s); \r\n    })(); \r\n    </script>\r\n    <?php\r\n}\r\n// Add hook for front-end <head></head>\r\n//add_action(\'wp_head\', \'add_screentracking_js\');\r\n\r\n//Load google tag manager script just below opening body tag\r\nadd_action( \'genesis_before\', \'addAfterBodyTag\' );\r\nfunction addAfterBodyTag() {\r\n    if ( current_filter() == \'genesis_before\' ){\r\n    ?>\r\n        <script>\r\n          dataLayer = [];\r\n        </script>\r\n    \r\n        <!-- Google Tag Manager -->\r\n        <noscript><iframe src=\"//www.googletagmanager.com/ns.html?id=GTM-M93PMB\"\r\n        height=\"0\" width=\"0\" style=\"display:none;visibility:hidden\"></iframe></noscript>\r\n        <script>(function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({\'gtm.start\':\r\n        new Date().getTime(),event:\'gtm.js\'});var f=d.getElementsByTagName(s)[0],\r\n        j=d.createElement(s),dl=l!=\'dataLayer\'?\'&l=\'+l:\'\';j.async=true;j.src=\r\n        \'//www.googletagmanager.com/gtm.js?id=\'+i+dl;f.parentNode.insertBefore(j,f);\r\n        })(window,document,\'script\',\'dataLayer\',\'GTM-M93PMB\');</script>\r\n        <!-- End Google Tag Manager -->\r\n        \r\n        <!-- IS+ Instant Search Widget -->\r\n        <script src=\"https://acp-magento.appspot.com/js/acp-magento.js?v=3&mode=woocommerce&UUID=a5c387f0-3d16-48a4-9ef2-5b9f6d64b8d6&store=1\"></script>\r\n        <!-- IS+ Instant Search Widget -->\r\n    <?php\r\n    }\r\n}\r\n\r\n\r\n//load conditional script\r\nadd_action(\'wp_footer\', \'_brgm_footer_scripts\');\r\nfunction _brgm_footer_scripts() { \r\n    if ( is_single() && is_singular( \'post\' ) ) { ?>\r\n<script>\r\n( function( $ ) {\r\n    $(document).ready( function() {\r\n        $(\'#commentform\').validate({\r\n            rules: { author: {required: true,minlength: 2},\r\n                email: { required: true, email: true },\r\n                comment: { required: true, minlength: 20 }\r\n            },\r\n            messages: {\r\n                author: \"Please enter your Name\",\r\n                email: \"Please enter a valid email address.\",\r\n                comment: \"Please enter your comment\"\r\n            },\r\n            errorElement: \"div\",\r\n            errorPlacement: function(error, element) {\r\n                element.after(error);\r\n            }\r\n        \r\n        });\r\n    });\r\n})(jQuery);\r\n</script>\r\n<?php    \r\n    }\r\n    if ( is_page(7) ) { \r\n        $section = isset( $_GET[\'section\'] ) ? $_GET[\'section\'] : false;\r\n        if ( !$section ) return false;\r\n        echo \"<script>\\n( function($) {\\n\\t$(document).ready( function() {\\n\";\r\n        echo \"\\t\\t$(\'.section\').hide();\\n\";\r\n        echo \"\\t\\t$(\'#$section\').show().addClass(\'active\');\\n\";\r\n        echo \"\\t\\t$(\'.account-menu a[href=\\\"#$section\\\"]\').addClass(\'active\');\\n\";\r\n        echo \"});\\n})(jQuery);\\n</script>\";\r\n    }\r\n}\r\n\r\n// add element before header \r\nadd_action(\'cmk/before/header/title\', \'_bg_before_header\');\r\nfunction _bg_before_header() {\r\n    echo \'<div class=\"header-left-area\"><span class=\"top-connect\">LOVE BOARD GAMES...</span>\';\r\n    wp_nav_menu( array(\r\n        \'menu\'          => \'Top Social Icon\',\r\n        \'menu_class\'    => \'icon-list\',\r\n    ));\r\n    echo \'</div>\';\r\n}\r\n\r\n//Add Text before header logo\r\nadd_filter(\'cmk/logo/html\', \'_brgd_before_logo\');\r\nfunction _brgd_before_logo( $html ) {\r\n    return \'<span class=\"free-ship\">Free Shipping On Orders $75+</span>\'.$html;\r\n}\r\n\r\n//ACCOUNT & LOGIN STUFF\r\n//\r\n//\r\n//Redirect people on logout back to homepage\r\nadd_action(\'wp_logout\',\'go_home\');\r\nfunction go_home(){\r\n  wp_redirect( home_url() );\r\n  exit();\r\n}\r\n\r\n// show admin bar only for admins\r\nif (!current_user_can(\'manage_options\')) {\r\n	add_filter(\'show_admin_bar\', \'__return_false\');\r\n}\r\n\r\n//Changes the login error to be more vague about which part was wrong.\r\nfunction login_error_override()\r\n{\r\n    return \'Incorrect login details.\';\r\n}\r\nadd_filter(\'login_errors\', \'login_error_override\');\r\n\r\nfunction custom_login_page() {\r\necho \'<link rel=\"stylesheet\" type=\"text/css\" href=\"\' . get_bloginfo(\'stylesheet_directory\') . \'/login/custom-login-styles.css\" />\';\r\n}\r\nadd_action(\'login_head\', \'custom_login_page\');\r\n\r\n//Admin/PW reset login page\'s logo now redirects to homepage instead of wp\r\nfunction my_login_logo_url() {\r\nreturn get_bloginfo( \'url\' );\r\n}\r\nadd_filter( \'login_headerurl\', \'my_login_logo_url\' );\r\n\r\nfunction my_login_logo_url_title() {\r\nreturn \'BoardGames.com - The Home Of BoardGames\';\r\n}\r\nadd_filter( \'login_headertitle\', \'my_login_logo_url_title\' );\r\n\r\n//Redirects any non admin who happened upon this to the homepage\r\nfunction non_admin_login_redirect( $redirect_to, $request, $user )\r\n{\r\nglobal $user;\r\nif( isset( $user->roles ) && is_array( $user->roles ) ) {\r\n    if( in_array( \"administrator\", $user->roles ) ) {\r\n        return $redirect_to;\r\n    } else {\r\n        return home_url();\r\n    }\r\n}\r\nelse\r\n{\r\n    return $redirect_to;\r\n}}\r\nadd_filter(\"login_redirect\", \"non_admin_login_redirect\", 10, 3);\r\n\r\n\r\n//HOMEPAGE HEADER STUFF\r\n//\r\n//\r\n// Add element before header search \r\nadd_action(\'genesis_header_right\', \'_bg_sign_help\');\r\nfunction _bg_sign_help() {\r\n    $text = ( !is_user_logged_in() ) ? \'<a href=\"/account\">Sign In</a>\' \r\n            : \'<a href=\"\'.wp_logout_url(home_url()).\'\">Logout</a>\';\r\n    echo \"<div class=\'top-help\'>{$text}<a class=\'qhelp\' href=\'/contact\'>Help</a></div>\";\r\n}\r\n//add facebook login link\r\nadd_action(\'woocommerce_login_form_start\', \'_bg_facebook_login\' );\r\nfunction _bg_facebook_login() {\r\n    echo BG_Facebook::login_link();\r\n}\r\n\r\n// change search text placeholder\r\nadd_filter( \'genesis_search_text\', \'_brgm_search_text\' );\r\nfunction _brgm_search_text( $text ) {\r\n	return esc_attr( \'Search the Blog...\' );\r\n}\r\n\r\n//remove woocommerce breadcrubs\r\nremove_action( \'woocommerce_before_main_content\', \'woocommerce_breadcrumb\', 20, 0 );\r\n\r\nadd_shortcode(\'brgm_post\', \'_brgm_get_post\');\r\nfunction _brgm_get_post( $atts ) {\r\n    $a = shortcode_atts( array(\r\n        \'post_type\'         => \'post\',\r\n        \'posts_per_page\'     => 5,\r\n        \'order\'             => \'DESC\',\r\n        \'orderby\'           => \'date\',\r\n        \'include\'           => \'\',  \r\n        \'exclude\'           => \'\', \r\n        \'type\'              => \'\',\r\n    ), $atts);\r\n    if ( $a[\'include\'] ) $a[\'category__in\'] = explode(\',\', $a[\'include\'] );\r\n    if ( $a[\'exclude\'] ) $a[\'category__not_in\'] = explode(\',\', $a[\'exclude\'] );\r\n    $query = new WP_QUery( $a ); \r\n    $posts = $query->get_posts(); \r\n    $item = \'<div class=\"post-list clear\">\';\r\n    foreach ( $posts as $post ) {\r\n        if ( $a[\'type\'] === \'title\' ) {\r\n            $item .= \'<h5 class=\"title-on\"><a href=\"\'.get_the_permalink( $post->ID ).\'\">\'.$post->post_title.\'</a></h5>\';\r\n        } else {\r\n            $item .= \'<div class=\"brgmp-info\"><div class=\"img-left\"><a href=\"\'.get_the_permalink( $post->ID ).\'\">\'. get_the_post_thumbnail( $post->ID, \'medium\' ) .\'</a></div>\';\r\n            $item .= \'<div class=\"list-right\"><h5><a href=\"\'.get_the_permalink( \r\n                    $post->ID ).\'\">\'.$post->post_title.\'</a></h5>\';\r\n            $item .= \'<span class=\"date\">\'.date(\'F jS, Y\', strtotime( $post->post_date ) ).\'</span>\';\r\n            $item .= \'<p class=\"excerpt\">\'.substr($post->post_content, 0, 150).\'<a href=\"\'.get_the_permalink( $post->ID ).\'\"> (Read more...)</a></p></div></div>\';\r\n        }\r\n    }\r\n    $item .= \'</div>\';\r\n    return $item;\r\n}\r\n/* \r\n * Single Product Customization \r\n */\r\n \r\n// Load add to list button & share after thumbnails\r\nadd_action(\'woocommerce_product_thumbnails\',\'_bg_list_buttons\', 25);\r\nfunction _bg_list_buttons() {\r\n    global $br_wclist;\r\n	echo \'<div class=\"cm-desktop\">\'.$br_wclist->load( get_the_id() );\r\n	echo \'<div class=\"social-share\">\';\r\n	$to = \'mailto:?subject=Check%20this%20out%20\'.get_the_title().\'&amp;body=I%20saw%20this%20on%20BoardGames.com%20and%20thought%20of%20you%20\'.get_the_permalink();\r\n	echo _bg_share($to, \'<i class=\"fa fa-envelope\"></i> Share with Email\', \'mail\', false);\r\n	echo \'<div class=\"fb-like\" data-href=\"\'.get_the_permalink().\'\" data-layout=\"button\" data-action=\"like\" data-show-faces=\"true\" data-share=\"true\"></div>\';\r\n    echo \'<div id=\"fb-root\"></div>\r\n        <script>(function(d, s, id) {\r\n          var js, fjs = d.getElementsByTagName(s)[0];\r\n          if (d.getElementById(id)) return;\r\n          js = d.createElement(s); js.id = id;\r\n          js.src = \"//connect.facebook.net/en_GB/sdk.js#xfbml=1&version=v2.6&appId=748091538669166\";\r\n          fjs.parentNode.insertBefore(js, fjs);\r\n        }(document, \\\'script\\\', \\\'facebook-jssdk\\\'));</script>\';\r\n	echo \'</div></div>\';\r\n}\r\n\r\n//social share link generate\r\nfunction _bg_share( $url, $text, $cl = \'\', $open = true) {\r\n    $script = ( $open ) ? \'onclick=\"javascript:window.open(this.href,\\\'\\\', \\\'menubar=no,toolbar=no,\'.\r\n                \'resizable=yes,scrollbars=yes,height=600,width=600\\\');return false;\"\': \'\' ;\r\n    $link = ( $open ) ? $url.get_the_permalink( get_the_ID() ) : $url;\r\n    return \'<a class=\"bg-share \'.$cl.\'\" href=\"\'.$link.\'\" \'.$script.\'>\'.$text.\'</a>\';\r\n}\r\n\r\n// Add featured image to gallery list\r\nadd_filter(\'woocommerce_product_gallery_attachment_ids\', \'_br_modify_product_gallery\' );\r\nfunction _br_modify_product_gallery( $ids ) {\r\n    $ids[] = get_post_meta(get_the_ID(), \'_thumbnail_id\', true);\r\n    return array_reverse( $ids );\r\n}\r\n\r\n//no longer remove woocommerce sale flash - overrode the sale_flash templates instead\r\n//remove_action(\'woocommerce_before_single_product_summary\', \'woocommerce_show_product_sale_flash\', 10);\r\n#add_action(\'woocommerce_product_thumbnails\', \'woocommerce_show_product_sale_flash\', 26);\r\n\r\n//Customize woocommerce html price output\r\nadd_filter( \'woocommerce_get_price_html\', \'_bg_price_output\', 10, 2 );\r\nfunction _bg_price_output( $p, $i ) {\r\n	$e = $i->is_on_sale() ? round( ( ( $i->regular_price - $i->sale_price ) / $i->regular_price ) * 100 ) : $p;\r\n	return is_single() && is_main_query() && $i->is_on_sale() ? str_replace( \r\n        array(\'</ins>\',\'</del>\'), array(\r\n            \' BG Price <span class=\"off\">\'.$e.\'% Off</span></ins>\',\r\n            \'<span> Reg. Price</span></del>\'\r\n        ), $p \r\n    ) : $p ;\r\n}\r\n\r\n// remove product meta, tabs, related and add custom data \r\nremove_action(\'woocommerce_single_product_summary\', \'woocommerce_template_single_meta\', 40);\r\nremove_action(\'woocommerce_after_single_product_summary\', \'woocommerce_output_product_data_tabs\', 10);\r\nremove_action(\'woocommerce_after_single_product_summary\', \'woocommerce_upsell_display\', 15);\r\nremove_action(\'woocommerce_after_single_product_summary\', \'woocommerce_output_related_products\', 20);\r\n\r\nadd_action(\'woocommerce_after_single_product_summary\', \'_bg_custom_product_data\', 11);\r\nfunction _bg_custom_product_data() {\r\n    global $product, $post;\r\n    echo \'<div class=\"br-product-data\">\';\r\n    echo \'<div class=\"left-data\"><h2>BG SCORECARD</h2>\';\r\n    //woocommerce_template_single_rating();\r\n    _brgm_rating_display();\r\n    printf( _n( \'%s Star\', \'%s Stars\', $product->get_average_rating(), \'bgrm\' ), \r\n        \'<span class=\"rating-count\">\' . $product->get_average_rating() . \'</span>\' );\r\n    echo \'<div class=\"complexity-rating crating\">\'._bg_custom_rating_output(\'complexity\').\'</div>\';\r\n    echo \'<div class=\"skill-rating crating\">\'._bg_custom_rating_output(\'skill\').\'</div>\';\r\n    echo \'<div class=\"intensity-rating crating\">\'._bg_custom_rating_output(\'intensity\').\'</div>\';\r\n    if( _get_bg_terms( 76 ) ) {\r\n        echo \'<div class=\"bg-stamps\"><h3>BG Stamps of Approval:</h3>\'._get_bg_terms(76, \'stamp\'). \'</div>\';\r\n    }\r\n    if( _get_bg_terms( 68 ) ) {\r\n        echo \'<div class=\"bg-awards\"><h3>Awards</h3>\'._get_bg_terms( 68, \'award\' ). \'</div>\';\r\n    }\r\n    echo \'</div><div class=\"right-data\">\';\r\n    echo \'<div class=\"rd-top\">\r\n            <span class=\"num\"><i class=\"fa fa-users\"></i>\'._bg_attr(\'pa_min-players\').\'-\'._bg_attr(\'pa_max-players\').\'<br>Players</span>\r\n            <span class=\"game-time\"><i class=\"fa fa-clock-o\"></i>\'.xz0( _get_bg_terms(37, \'\', \'title\') ) .\'</span>\r\n            <span class=\"game-age\"><i class=\"fa fa-birthday-cake\"></i>\'.xz0( _get_bg_terms(35, \'\', \'title\') ).\'</span>\r\n            </div>\';\r\n    echo \'<div class=\"inside-box\"><h3>What\\\'s in the box</h3><div style=\"margin-left:25px !important;\">\'._br_get_meta(\'_brgm_witb\', \'\', false).\'</div></div>\';\r\n    \r\n    echo \'<div class=\"terms-list\"><p class=\"term-type\">Type:<span class=\"va\">\'._get_bg_terms( 39, \'\', \'\' ).\'</span></p>\';\r\n    echo \'<p class=\"term-format\">Format:<span class=\"va\">\'._get_bg_terms( 47, \'\', \'\').\'</p>\';\r\n    echo \'<p class=\"term-theme\">Theme:<span class=\"va\">\'._get_bg_terms( 41, \'\', \'\').\' </p>\';\r\n    echo \'<p class=\"term-mechanics\">Mechanics:<span class=\"va\">\'._get_bg_terms( 45, \'\', \'\').\'</p>\';\r\n    echo \'<p class=\"term-company\">Company:<span class=\"va\">\'.getAttrLink(\'pa_publisher\').\'</p>\';\r\n    echo \'<p class=\"term-designer\">Designer:<span class=\"va\">\'.getAttrLink(\'pa_designer\').\'</p>\';\r\n    echo \'<p class=\"term-expansoins\">Expansions:<span class=\"va\">\'._bg_related_products().\'</p></div>\';\r\n    echo \'<div class=\"addto-el\"><button type=\"button\" class=\"button catc\">Add to cart</button></div>\';\r\n    echo \'</div></div>\'; // end of bg scored section\r\n    if ( _bg_quick_vid() ) {\r\n        echo \'<div class=\"video-section\"><h2>\'.get_the_title().\' Video:</h2>\';\r\n        echo _bg_quick_vid();\r\n        echo \'</div>\';\r\n    }\r\n    if ( $post->post_content ) \r\n        echo \'<article class=\"product-info\"><h2>Additional Product Details:</h2>\'.wpautop($post->post_content).\'</article>\';\r\n    comments_template();\r\n    echo _brgm_recently_viewed();\r\n    echo \'<div class=\"related\"><h2 class=\"bord\"><span>Related Games</span></h2>\';\r\n    echo _brgm_carousel( get_post_meta(get_the_ID(), \'_upsell_ids\', true) );\r\n    echo \'</div>\';\r\n}\r\n\r\n//Get attribute link\r\nfunction getAttrLink($AttrTaxName)\r\n{\r\n    global $product;\r\n    $output = \'\';\r\n    $terms = get_the_terms( $post->ID, $AttrTaxName );\r\n\r\n    if ( $terms && ! is_wp_error( $terms ) ) : \r\n    \r\n    	foreach ( $terms as $term ) {\r\n    		$output .= \'<a href=\"\'.get_term_link($term).\'\">\'.$term->name.\'</a> \';\r\n    	}\r\n    \r\n    endif; \r\n	return $output;\r\n}\r\n\r\nadd_action(\'woocommerce_after_single_product_summary\',\'_bg_list_buttons_mobile\', 10);\r\nfunction _bg_list_buttons_mobile() {\r\n    global $br_wclist;\r\n    /*\r\n	echo \'<div class=\"cm-mobile\">\'.$br_wclist->load( get_the_id() );\r\n	echo \'<div class=\"social-share\">\';\r\n	echo _bg_share(\'https://www.facebook.com/sharer/sharer.php?u=\', \r\n	   \'<i class=\"fa fa-facebook\"></i> Share on Facebook\', \'fb\');\r\n	$to = \'mailto:?subject=Check%20this%20out%20\'.get_the_title().\'&amp;body=I%20saw%20this%20on%20BoardGames.com%20and%20thought%20of%20you%20\'.get_the_permalink();\r\n	echo _bg_share($to, \'<i class=\"fa fa-envelope\"></i> Share with Email\', \'mail\', false);\r\n	echo _bg_share(\'https://plus.google.com/share?url=\', \'<i class=\"fa fa-google-plus\"></i> Share with Google Plus\');\r\n	echo \'</div></div>\';\r\n	*/\r\n	echo \'<div class=\"cm-mobile\">\'.$br_wclist->load( get_the_id() );\r\n	echo \'<div class=\"social-share\">\';\r\n	echo _bg_share(\'https://www.facebook.com/sharer/sharer.php?u=\', \'<i class=\"fa fa-facebook\"></i> Share \', \'fb\');\r\n	echo \' \';\r\n	$to = \'mailto:?subject=Check%20this%20out%20\'.get_the_title().\'&amp;body=I%20saw%20this%20on%20BoardGames.com%20and%20thought%20of%20you%20\'.get_the_permalink();\r\n	echo _bg_share($to, \'<i class=\"fa fa-envelope\"></i> Send Email\', \'mail\', false);\r\n	echo _bg_share(\'https://plus.google.com/share?url=\', \'<i class=\"fa fa-google-plus\"></i> Share\',\"google\");\r\n	echo \'</div></div>\';\r\n}\r\n\r\n// customize single rating output\r\nfunction _brgm_rating_display() {\r\n    ob_start();\r\n    woocommerce_template_single_rating();\r\n    $rating = ob_get_clean();\r\n    echo str_replace( \r\n        array(\'customer\',\'(\', \')\'), array(\'\',\'\',\'\'), \r\n        $rating\r\n    );\r\n}\r\n\r\n//get assigned ratings attribute\r\nfunction _bg_custom_rating_output( $rating ) {\r\n    $ra = str_repeat(\'<i></i>\', 7);\r\n    if ( $rating === \'complexity\')\r\n        return $ra.\'<span style=\"width:\'._bg_attr(\'pa_complexity-level\', 8).\'%;\"></span>\';\r\n    else if ( $rating === \'skill\')\r\n        return $ra.\'<span style=\"width:\'._bg_attr(\'pa_skill-level\', 8).\'%;\"></span>\';\r\n    else if ( $rating === \'intensity\')\r\n        return $ra.\'<span style=\"width:\'._bg_attr(\'pa_intensity-level\', 8).\'%;\"></span>\';\r\n}\r\n\r\n//quick video list\r\nfunction _bg_quick_vid() {\r\n    $sum = _br_get_meta(\'_brgm_video_sum\');\r\n    $howto =_br_get_meta(\'_brgm_video_howto\', \'Hot To Play \'.get_the_title() );\r\n    $rev = _br_get_meta(\'_brgm_video_review\', get_the_title(). \' Reviews\' );\r\n    $gplay = _br_get_meta(\'_brgm_video_gameplay\', \'Watch \'.get_the_title() );\r\n    if ( !$sum && !$howto && !$rev && !$gplay ) return false;\r\n    $vid = \'<div class=\"quick-vid\">\'.$sum.\'</div>\';\r\n    $vid .= \'<div class=\"howto-vid\">\'.$howto.\'</div>\';\r\n    $vid .= \'<div class=\"review-vid\">\'.$rev.\'</div>\';\r\n    $vid .= \'<div class=\"gameplay-vid last\">\'.$gplay.\'</div>\';\r\n    return $vid;\r\n}\r\n\r\nfunction _br_get_meta($key, $label=false, $vid = true) {\r\n    $data = get_post_meta(get_the_ID(), $key, true );\r\n    if( !$data) return false;\r\n    $video = \'<div class=\"res-embed\"><iframe width=\"560\" height=\"315\" src=\"\'.$data;\r\n    $video .= \'\" frameborder=\"0\" allowfullscreen></iframe></div>\';\r\n    return ( $vid ) ? \'<span class=\"vid-label\">\'.$label.\'</span>\'. $video : $label.$data;\r\n}\r\n//pull attribute value\r\nfunction _bg_attr( $name, $percent = false, $key = null ) {\r\n    global $product;\r\n    if ( !$product ) return false;\r\n    $atts =  $product->get_attribute( $name ) ;\r\n    return ( $percent ) ? number_format( (int) $atts / (int) $percent * 100 ) : $atts ;\r\n}\r\n\r\n// get product assigned category\r\nfunction _get_bg_terms( $parent, $cl = null, $type = \'image\' ) {\r\n    $terms = wp_get_post_terms( get_the_ID(), \'product_cat\');\r\n    if ( !$terms ) return false;\r\n    $out = \'\';\r\n    foreach ( $terms as $obj => $term ) {\r\n        if ( $term->parent === $parent ) {\r\n            if ( $type === \'image\' ) {\r\n                $out .= \'<a href=\"\'.get_term_link( $term ).\'\" target=\"_blank\"><span class=\"item-\'.$cl.\' \'.\r\n                    $term->slug.\'\">\'.wp_get_attachment_image(\r\n                    get_woocommerce_term_meta( $term->term_id, \'thumbnail_id\', true ), \'full\' ).\'</span></a>\';\r\n            } else if ( $type === \'title\') {\r\n                $out .= $term->name;\r\n            } else {\r\n                $out .= \'<a href=\"\' . esc_url( get_term_link( $term ) ) . \'\" target=\"_blank\">\' . $term->name . \'</a>\';\r\n            }\r\n        }\r\n    }\r\n    return $out;\r\n}\r\n\r\n// Add line-breaks between string\r\nfunction xz0( $s ) {\r\n    $count = strlen( $s ) / 1.5;\r\n    return wordwrap( $s, $count, \'<br>\');\r\n}\r\n\r\n// change default text\r\nadd_filter( \'gettext\', \'_bg_default_text\', 20, 3 );\r\nfunction _bg_default_text( $translated_text, $text, $domain ) {\r\n	switch ( $translated_text ) {\r\n		case \'In stock\' :\r\n        $translated_text = __( \'Ready to ship!\', \'woocommerce\' );\r\n        break;\r\n	}\r\n	return $translated_text;\r\n}\r\n\r\n//get related products\r\nfunction _bg_related_products() {\r\n    $ids = get_post_meta(get_the_ID(), \'_upsell_ids\', true);\r\n    if ( !$ids ) return false;\r\n    $args = array( \r\n        \'post_type\'         => \'product\', \r\n        \'posts_per_page\'    => -1,\r\n        \'orderby\'           => \'rand\',\r\n        \'post__in\'          => $ids,\r\n    );\r\n    $query = new WP_Query( $args );\r\n    $product = $query->get_posts();\r\n    $items = \'\';\r\n    foreach ( $product as $item ) {\r\n        $sept = ( $item === end( $product )  ) ? \'\' : \',\' ;\r\n        $items .= \'<span><a href=\"\'. get_the_permalink( $item->ID ) .\'\">\'. \r\n        $item->post_title .\'</a>\'.$sept.\'</span>\';\r\n    }\r\n    return $items;\r\n}\r\n\r\n//modify review form\r\nadd_filter( \'woocommerce_product_review_comment_form_args\', \'_bg_review_form\' );\r\nfunction _bg_review_form( $c ) {\r\n    $c[\'title_reply\']   = \'Rate & Review this Game:\';\r\n    $c[\'label_submit\']  = \'Write a Review\';\r\n    return $c;\r\n}\r\n\r\n// Add login form for non-loggedin user\r\nadd_action(\'genesis_after_footer\', \'_bg_login_form\');\r\nfunction _bg_login_form() {\r\n    echo ( !is_user_logged_in() && is_product() ) ? \r\n        \'<div id=\"bglog\"><a class=\"bglog\" href=\"#bglog\"></a>\'.\r\n        do_shortcode(\'[woocommerce_my_account]\').\'</div>\' : \'\' ;\r\n}\r\n\r\n// get recently viewed item\r\nfunction _brgm_recently_viewed() {\r\n    if ( !isset( $_COOKIE[\'woocommerce_recently_viewed\'] ) ) return false;\r\n    $ids = explode(\'|\', $_COOKIE[\'woocommerce_recently_viewed\'] );\r\n    $wrapper = \'<div class=\"recently-viewed\"><h2 class=\"bord\"><span>Recently Viewed:</span></h2>\'._brgm_carousel( $ids );\r\n    return $wrapper.\'</div>\';\r\n}\r\n\r\n// carousel creator\r\nfunction _brgm_carousel( $ids, $arg = null, $type = false ) {\r\n    if ( !$ids && !$arg ) return false;\r\n    \r\n    $args = ( $arg ) ? $arg : array(\r\n        \'post_type\'     => \'product\',\r\n        \'post_per_page\' => 20,\r\n        \'post__in\'      => $ids,\r\n    );\r\n    //Exclude certain items from all display, so far only Players Club\r\n    $exclude_IDs = array(2244);\r\n    $args[\'post__not_in\'] = $exclude_IDs;\r\n    \r\n    $query = new WP_QUery( $args ); \r\n    $posts = $query->get_posts(); \r\n    $item = \'<ul class=\"bg-item-list carousel\">\';\r\n    foreach ( $posts as $post ) {\r\n        $prod = wc_get_product( $post->ID );\r\n        /*$cart = \'<a rel=\"nofollow\" href=\"\'.$prod->add_to_cart_url()\r\n            .\'\" data-quantity=\"1\" data-product_id=\"\'.$prod->id\r\n            .\'\" data-product_sku=\"\'.$prod->get_sku().\'\" class=\"atc ajax_add_to_cart\">\'\r\n            .$prod->add_to_cart_text().\'</a>\';*/\r\n        $cart = do_shortcode(\'[add_to_cart style=\"padding: 3px !important;\" show_price=\"false\" id=\'.$post->ID.\']\');\r\n        $price = ( !$prod->is_on_sale() ) ? \'<span class=\"regular-price\">$\'\r\n                .$prod->get_price().\'</span>\':\r\n             \'<span class=\"sale-price\">$\'.$prod->get_regular_price().\'</span>\'.\r\n             \'<span class=\"regular-price\">$\'.$prod->get_price().\'</span>\';\r\n        if ( !$prod->get_price() ) $price = \'\';\r\n        if ( $type === \'image\' ) {\r\n            $item .= \'<li class=\"item\"><a href=\"\'.get_the_permalink( $post->ID ).\'\">\'\r\n                    .wp_get_attachment_image( \r\n                        get_post_thumbnail_id( $post->ID ), \'thumbnail\' ).\'</li>\';\r\n        } else {\r\n            $item .= \'<li class=\"item\"><a href=\"\'.get_the_permalink( $post->ID ).\'\">\'\r\n                    .wp_get_attachment_image( \r\n                        get_post_thumbnail_id( $post->ID ), \'thumbnail\' )\r\n                    .\'<span class=\"item-title\">\'.$post->post_title\r\n                    .\'</a></span>\'.$price.$cart.\'</li>\';\r\n        }\r\n    }\r\n    $item .= \'</ul>\';\r\n    return $item;\r\n}\r\n\r\n//create carousel shortcode\r\nadd_shortcode(\'brgm_slider\', \'_brmg_carousel_shortcode\');\r\nfunction _brmg_carousel_shortcode( $atts ) {\r\n    $a = shortcode_atts( array(\r\n        \'post_type\'     => \'product\',\r\n        \'post_per_page\' => 15,\r\n        \'cat\'           => 0,\r\n        \'order\'         => \'DESC\',\r\n        \'orderby\'       => \'date\',\r\n        \'featured\'      => \'\',  \r\n        \'sale\'          => \'\',\r\n        \'stock_status\'  => \'instock\',\r\n        \'type\'          => \'\'\r\n    ), $atts);\r\n    \r\n    //Always only show in stock\r\n    $a[\'meta_query\'][] =  array(\r\n            \'key\' => \'_stock_status\',\r\n            \'value\' => \'instock\'\r\n        );\r\n    \r\n    if ( $a[\'sale\'] === \'yes\' ) {\r\n        $a[\'meta_query\'] = array(\r\n            \'relation\' => \'AND\',array(\r\n            \'relation\' => \'OR\',\r\n                array( \r\n                    \'key\'           => \'_sale_price\',\r\n                    \'value\'         => 0,\r\n                    \'compare\'       => \'>\',\r\n                    \'type\'          => \'numeric\'\r\n                ),\r\n                array( \r\n                    \'key\'           => \'_min_variation_sale_price\',\r\n                    \'value\'         => 0,\r\n                    \'compare\'       => \'>\',\r\n                    \'type\'          => \'numeric\'\r\n                )),\r\n                array(\r\n                    \'key\' => \'_stock_status\',\r\n                    \'value\' => \'instock\',\r\n                    )\r\n        );\r\n    } else if ( $a[\'featured\'] === \'yes\' ) {\r\n        $a[\'meta_value\']    = \'yes\';\r\n        $a[\'meta_key\']      = \'_featured\';\r\n    } else if ( $a[\'cat\'] !== 0 ) {\r\n        $a[\'taxonomy\'] = \'product_cat\';\r\n        $a[\'term\'] = $a[\'cat\'];\r\n    } else if(isset($atts[\'custom_sort\'])){\r\n            if ($atts[\'custom_sort\'] === \'best_selling\'){\r\n            $a[\'meta_key\'] = \'total_sales\';\r\n            $a[\'orderby\'] = \'meta_value_num\';\r\n            $a[\'order\'] = \'desc\';\r\n            } else if ($atts[\'custom_sort\'] === \'top_rated\'){\r\n                 $a[\'orderby\'] = \'meta_value_num\';\r\n                 $a[\'meta_key\'] = \'_wc_average_rating\';\r\n                 $a[\'order\'] = \'desc\';\r\n            } else if ($atts[\'custom_sort\'] === \'newest\'){\r\n                 $a[\'orderby\'] = \'date\';\r\n                 $a[\'order\'] = \'desc\';\r\n        }\r\n    } else {\r\n        $a[\'meta_query\'][] =  array(\r\n            \'key\' => \'_price\',\r\n            \'value\' => \' \',\r\n            \'compare\' => \'!=\',\r\n            \'type\' => \'NUMERIC\'\r\n        );\r\n    }\r\n    \r\n    return _brgm_carousel( \'\', $a, $a[\'type\'] );\r\n}\r\n\r\nadd_shortcode(\'brgm_top10_lists\', \'_brmg_top10lists_shortcode\');\r\nfunction _brmg_top10lists_shortcode( $atts ) {\r\n    if ( !is_null($atts[\'get_top_list_products\'] )) {\r\n        $listType = $atts[\'get_top_list_products\'];\r\n        $customerLists = \'love_it|want_it|have_it\';\r\n        //Exclude certain items from all display, so far only Players Club\r\n        $exclude_IDs = array(2244);\r\n        $args = array(\r\n            \'post_type\'     => \'product\',\r\n            \'post_per_page\' => 10,\r\n            \'post__not_in\'  => $exclude_IDs,\r\n            \'meta_query\'    => array(\r\n                array(\'key\' => \'_stock_status\',\'value\' => \'instock\'),\r\n            ),\r\n        );\r\n        \r\n        //backup plan to use the product categories instead of actual lists\r\n        if($atts[\'use_alt_prodcats_instead\'] == \'true\'){\r\n            //Spit out the info using the product shortcode instead\r\n            switch($listType){\r\n                case \'love_it\':\r\n                    $swaptoCategory = \'top-10-favorite-games\'; break;\r\n                case \'want_it\':\r\n                    $swaptoCategory = \'top-10-hot-games\'; break;\r\n                case \'have_it\':\r\n                    $swaptoCategory = \'top-10-games-sales\'; break;\r\n                default:\r\n                    return \'\';\r\n            }\r\n            return do_shortcode( \'[bgrm_product list=\"false\" cat=\"\'.$swaptoCategory.\'\"]\' );\r\n        }else{\r\n            if (strpos($customerLists, $listType) !== false) {\r\n                //This is one of the top 10 list generated from customers clicking have/own/love it\r\n                //$queryTxt = \"SELECT post_id FROM {$wpdb->prefix}postmeta WHERE meta_key=\'_brgm_\".\r\n                //$listType.\"_added\' AND meta_value > 0 ORDER BY meta_value desc LIMIT 10\";\r\n                $args[\'orderby\'] = \'meta_value_num\';\r\n                $args[\'meta_key\'] = \'_brgm_\'.$listType.\'_added\';\r\n                $args[\'order\'] = \'desc\';\r\n            }else if($listType == \'top_rated\'){\r\n                $args[\'orderby\'] = \'meta_value_num\';\r\n                $args[\'meta_key\'] = \'_wc_average_rating\';\r\n                $args[\'order\'] = \'desc\';\r\n            }\r\n            else if($listType == \'best_selling\'){\r\n                $args[\'meta_key\'] = \'total_sales\';\r\n                $args[\'orderby\'] = \'meta_value_num\';\r\n                $args[\'order\'] = \'desc\';\r\n            }\r\n            //now spit out the list\r\n            $query = new WP_Query( $args ); \r\n            $results = $query->get_posts();\r\n            \r\n            $item = \'<ol class=\"product-list\">\';\r\n            foreach ( $results as $post ) {\r\n                $prod = wc_get_product( $post->ID );\r\n                $item .= \'<li><a href=\"\'. $prod->get_permalink() .\'\" style=\"font-weight:bold;\">\'\r\n                .$prod->get_title().\'</a></li>\';\r\n            }\r\n            $item .= \'</ol>\';\r\n            return $item;\r\n        }\r\n    }\r\n}\r\n\r\n//create shortcode for -taxonomy\r\nadd_shortcode(\'brmg_tax\', \'_brgm_tax_query\');\r\nfunction _brgm_tax_query( $atts) {\r\n    $a = shortcode_atts( array(\r\n        \'slug\'      => \'\', \r\n        \'load\'      => \'\',\r\n        \'type\'      => \'\',\r\n        \'parent\'    => \'\',\r\n        \'column\'    => 999,\r\n        \'showtitle\' => false,\r\n        \'tax\'       => \'product_cat\',\r\n        \'orderby\'   => \'count\',\r\n        \'order\'     => \'DESC\',\r\n    ), $atts);\r\n	$slugs = ( !empty( $a[\'slug\'] ) ) ? explode(\',\', $a[\'slug\'] ) : \'\' ;\r\n    $item = \'<ul class=\"brgm-tax-list column-\'.$a[\'column\'].\' \'.$a[\'load\'].\'\">\';\r\n    if($a[\'type\'] === \'image\'){\r\n        $cats = get_terms( $a[\'tax\'], array(\r\n            \'hide_empty\'    => 0,\r\n            \'slug\'          => $slugs,\r\n            \'orderby\'       => $a[\'orderby\'], \r\n            \'order\'         => $a[\'order\'],\r\n            \'parent\'        => $a[\'parent\'],\r\n        ));\r\n    }elseif($a[\'type\'] === \'publisher_reduced\'){\r\n        $cats = get_terms( $a[\'tax\'], array(\r\n            \'hide_empty\'    => 0,\r\n            \'slug\'          => $slugs,\r\n            \'orderby\'       => $a[\'orderby\'], \r\n            \'order\'         => $a[\'order\'],\r\n            \'parent\'        => $a[\'parent\'],\r\n            \'number\'        => 18,\r\n        ));\r\n    }\r\n    else{\r\n        $cats = get_terms( $a[\'tax\'], array(\r\n            \'hide_empty\'    => 0,\r\n            \'slug\'          => $slugs,\r\n            \'orderby\'       => $a[\'orderby\'], \r\n            \'order\'         => $a[\'order\'],\r\n            \'parent\'        => $a[\'parent\'],\r\n        ));\r\n    }\r\n    $i = 0;\r\n   foreach ( $cats as $cat ) {\r\n        $i++;\r\n        $placeholder = false;\r\n        $c = ( count($cats) > 1 && ( $cat === end( $cats ) || $i % $a[\'column\'] == 0 )  ) ? \' last\' : \'\';\r\n        $title = ( $a[\'showtitle\'] ) ? \'<h3>\'.$cat->name.\'</h3>\' : \'\' ;\r\n        $catProdCount = $cat->count;\r\n        $img = wp_get_attachment_image(get_woocommerce_term_meta( $cat->term_id, \'thumbnail_id\', true ), \'full\' );\r\n        $cimg = get_term_meta ( $cat->term_id, \'_brgm_image\', true );\r\n        if ( !$img && $cimg ) $img = \'<img src=\"\'.$cimg.\'\" alt=\"\'.$cat->name.\'\" />\';\r\n        if ( !$img && !$cimg ) {\r\n            $img = \'<img src=\"/wp-content/uploads/2016/07/PAWN-ICON.jpg\" alt=\"\'.$cat->name.\'\" />\';\r\n            $placeholder = true;\r\n        }\r\n        if ( $a[\'type\'] === \'image\' || $a[\'type\'] === \'publisher_reduced\' ) {\r\n            $item .= \'<li class=\"item\"><a href=\"\'.get_term_link( $cat->term_id ).\'\">\'.$img.\'</a></li>\';\r\n        } else if ( $a[\'type\'] === \'data\' ) {\r\n            //Check to see if we have any products in stock by this Publisher.  If not, do not show\r\n            if( $catProdCount > 0){\r\n                if(!$placeholder){\r\n                    /*$item .= \'<li class=\"item\'.$c.\'\" style=\"min-height:199px;\"><div style=\"height:156px;vertical-align:middle;display:table-cell;min-width:195px;\">\'.$title.\'<a href=\"\'.get_term_link( $cat->term_id ).\'\">\'.$img.\'</a></div>\';\r\n                    $tagline = get_term_meta( $cat->term_id, \'_brgm_tagline\', true );\r\n                    $item .= \'<div style=\"height:43px;vertical-align:middle;display:table-cell;min-width:195px;float:left;\"><span class=\"cat-dest\">\'.$tagline.\'</span><a href=\"\'.get_term_link( $cat->term_id ).\'\">View All: \'.$cat->name.\'</a></div></li>\';*/\r\n                    $item .= \'<li class=\"item\'.$c.\'\" style=\"min-height:199px;\">\'.$title.\'<a href=\"\'.get_term_link( $cat->term_id ).\'\">\'.$img.\'</a>\';\r\n                    $tagline = get_term_meta( $cat->term_id, \'_brgm_tagline\', true );\r\n                    $item .= \'<span class=\"cat-dest\">\'.$tagline.\'</span><a href=\"\'.get_term_link( $cat->term_id ).\'\"> \'.$cat->name.\'</a>(\'.$catProdCount.\')</li>\';\r\n                }else{\r\n                    $item .= \'<li class=\"item\'.$c.\'\">\'.$title.\'<a href=\"\'.get_term_link( $cat->term_id ).\'\">\'.$img.\'</a>\';\r\n                    $tagline = get_term_meta( $cat->term_id, \'_brgm_tagline\', true );\r\n                    $item .= \'<span class=\"cat-dest\">\'.$tagline.\'</span><a href=\"\'.get_term_link( $cat->term_id ).\'\"> \'.$cat->name.\'</a>(\'.$catProdCount.\')</li>\';\r\n                }\r\n            }\r\n        } else {\r\n            $item .= \'<li class=\"one-fifth\'.$c.\'\"><a href=\"\'.get_term_link( $cat->term_id ).\'\">\'.$img.\'<span class=\"term-name\">\'.$cat->name.\'</span></a><span class=\"term-desc\">\'.$cat->description.\'</span></li>\';\r\n        }\r\n    }\r\n    $item .= \'</ul>\';\r\n    return $item;\r\n}\r\n\r\n//get product shortcode \r\nadd_shortcode(\'bgrm_product\' , \'_bgrm_products\');\r\nfunction _bgrm_products( $atts ) {\r\n    $a = shortcode_atts( array(\r\n        \'count\' => 10,\r\n        \'sort\'  => \'have_it\',\r\n        \'cat\'   => \'\',\r\n        \'list\'  => true\r\n    ), $atts);\r\n    $arg = array(\r\n        \'post_type\'         => \'product\',\r\n        \'posts_per_page\'    => $a[\'count\'],\r\n        \'orderby\'           => \'date\',\r\n    );\r\n    if ( $a[\'list\'] === true ) {\r\n        $arg[\'meta_key\']    = \'_brgm_\'.$a[\'sort\'].\'_added\';\r\n        $arg[\'orderby\']     = \'meta_value_num title\';\r\n        $arg[\'order\']       = \'ASC\';\r\n    }\r\n    if ( $a[\'cat\'] ) {\r\n        $arg[\'taxonomy\'] = \'product_cat\';\r\n        $arg[\'term\'] = $a[\'cat\'];\r\n    }\r\n    $query = new WP_QUery( $arg ); //Run First Query\r\n    $posts = $query->get_posts(); \r\n    $out = \'<ol class=\"product-list\">\';\r\n    $item = array();\r\n    foreach ( $posts as $post ) {\r\n        $item[] = \'<li><a href=\"\'. get_the_permalink( $post->ID ).\'\">\'.$post->post_title.\'</a></li>\';\r\n    }\r\n    return $out. implode(\"\\n\", $item). \'</ol>\';\r\n    //echo \'<pre>\', print_r( $arg, 1), \'</pre>\';\r\n}\r\n\r\n// Customize Product Class for Ready To ship\r\nfunction _modify_stock_class( $av, $this ) {\r\n    if ( !is_product() ) return $av;\r\n    global $product;\r\n    if ( $product->get_total_stock() > 5 ) {\r\n        $av[\'class\'] = \'in-stock rts\';\r\n    } else {\r\n        $av[\'class\'] = \'in-stock low\';\r\n    }\r\n    return $av;\r\n}\r\nadd_filter(\'woocommerce_get_availability\', \'_modify_stock_class\', 11, 2);\r\n\r\n// Add List product on account section\r\nadd_action(\'brgm/account/section\', \'_brgm_account_list_section\');\r\nfunction _brgm_account_list_section() {\r\n    global $br_wclist;\r\n    $want = \'<h4>GAMES I WANT</h4><p>Below are all the games you\\\'ve added to your WANT IT list</p>\';\r\n    $love = \'<h4>GAMES I LOVE</h4><p>Below are all the games you\\\'ve added to your LOVE IT list</p>\';;\r\n    $have = \'<h4>GAMES I OWN</h4><p>Below are all the games you\\\'ve added to your OWN IT list</p>\';;\r\n	echo $br_wclist->get_list(\'want_it\', \'games-i-want\', \'section\', \'full\', $want);\r\n	echo $br_wclist->get_list(\'love_it\', \'games-i-love\', \'section\', \'full\', $love);\r\n	echo $br_wclist->get_list(\'have_it\', \'games-i-own\', \'section\', \'full\', $have);\r\n}\r\n\r\n// Remove Woocommmerce navigation update\r\nremove_action(\'woocommerce_account_navigation\', \'woocommerce_account_navigation\');\r\n/*\r\n * Archive Layout \r\n */\r\n \r\n // Load Filter and add additional wrapper\r\nadd_action(\'wp_head\', \'_brgm_archive_format\');\r\nfunction _archive_filter() {\r\n    echo \'<div class=\"filter-result\">\';\r\n    do_action(\'brgm/filter/display\');\r\n    echo \'</div><div class=\"results-display\">\';\r\n}\r\nfunction _brgm_archive_close_tag() {\r\n    echo \'</div>\';\r\n}\r\nfunction _brgm_archive_format() {\r\n    if ( is_shop() || ( is_archive() && is_woocommerce() ) ) {\r\n        add_action(\'woocommerce_before_main_content\', \'_archive_filter\');\r\n        add_action(\'woocommerce_after_main_content\', \'_brgm_archive_close_tag\');\r\n    }\r\n}\r\n\r\n// Add additional class if product has rating\r\n#add_filter( \'post_class\', \'_bg_post_class\');\r\nfunction _bg_post_class( $classes ) {\r\n    global $product, $post;\r\n    #$classes = ( $product && $product->is_on_sale() ) ? \'\' : ;\r\n	#$rating = ( $product ) ? $product->get_average_rating() : null ;\r\n	#if ( $rating ) $classes[] = \'has-rating\';\r\n	#return $classes;\r\n}\r\n\r\n/*\r\n * Blog Customization\r\n */\r\n// Adding recently viewed and sale\r\nfunction brgm_blog() {\r\n    if ( is_single() || is_archive() || is_home() || is_search() ) return true;\r\n    return false;\r\n}\r\nadd_action(\'genesis_after_content\', \'_brgm_blog_products\', 25);\r\nfunction _brgm_blog_products() {\r\n    if ( brgm_blog() ) { \r\n        echo \'<div class=\"clear\"></div>\';\r\n        if ( _brgm_recently_viewed() ) {\r\n            echo _brgm_recently_viewed();\r\n        }\r\n        echo \'<div class=\"related\"><h2 class=\"bord\"><span>Game on Sale: </span></h2>\';\r\n        echo do_shortcode(\'[brgm_slider cat=\"discount-board-games\"]\');\r\n        echo \'</div>\';\r\n    }\r\n}\r\n\r\n// Modify breadcrumbs\r\nadd_filter( \'genesis_breadcrumb_args\', \'_brgm_breadcrumb_display\' );\r\nfunction _brgm_breadcrumb_display( $args ) {\r\n	$args[\'sep\'] = \' > \';\r\n	$args[\'labels\'][\'prefix\'] = \'\';\r\n    return $args;\r\n}\r\n\r\n// add blog banner\r\nadd_action(\'genesis_before_content\', \'_brgm_blog_heading\');\r\nfunction _brgm_blog_heading() {\r\n    if ( !brgm_blog() ) return;\r\n    echo \'<div class=\"blog-banner\"><img src=\"/wp-content/uploads/2016/05/bg-blog.jpg\" alt=\"Board Games Blog\"></div>\';\r\n}\r\n// Customize Post Meta\r\nadd_filter( \'genesis_post_info\', \'_brgm_post_meta\' );\r\nfunction _brgm_post_meta( $data ) {\r\n    if ( is_single() ) $data = \'By [post_author_posts_link]\'; \r\n    else if ( is_home() ) $data = \'[post_date]\'; \r\n	return $data;\r\n}\r\n\r\n// Add social icons & featured image\r\nadd_action(\'genesis_entry_content\', \'_brgm_before_entry\', 5);\r\nfunction _brgm_before_entry() {\r\n    if ( !is_singular( \'post\' ) ) return;\r\n    echo \'<div class=\"before-post-entry\">\';\r\n    echo \'<div class=\"brgm-post-img\">\'.get_the_post_thumbnail( get_the_ID(), \'full\' ). \'</div>\';\r\n    echo \'</div>\';\r\n}\r\n\r\n// Add comment like and social icons \r\nadd_action(\'genesis_entry_content\', \'_brgm_after_entry\', 20);\r\nfunction _brgm_after_entry() {\r\n    if ( !is_post_type(\'post\') ) return;\r\n    echo \'<div class=\"comment-share\">\';\r\n    echo \'<div class=\"fb-like\" data-href=\"\'.get_the_permalink().\'\" data-layout=\"button\" data-action=\"like\" data-show-faces=\"true\" data-share=\"true\"></div>\';\r\n    echo \'<a class=\"comment-link\" href=\"\'.get_the_permalink().\'#respond\">Comment</a>\';\r\n    echo \'<div id=\"fb-root\"></div>\r\n        <script>(function(d, s, id) {\r\n          var js, fjs = d.getElementsByTagName(s)[0];\r\n          if (d.getElementById(id)) return;\r\n          js = d.createElement(s); js.id = id;\r\n          js.src = \"//connect.facebook.net/en_GB/sdk.js#xfbml=1&version=v2.6&appId=748091538669166\";\r\n          fjs.parentNode.insertBefore(js, fjs);\r\n        }(document, \\\'script\\\', \\\'facebook-jssdk\\\'));</script>\';\r\n    echo \'</div>\';\r\n}\r\n// remove footer meta\r\nadd_filter( \'genesis_post_meta\', \'_brgm_footer_meta\' );\r\nfunction _brgm_footer_meta($post_meta) {\r\n	return false;\r\n}\r\n\r\n// Add post navigation\r\nadd_action( \'genesis_after_entry\', \'_brgm_post_navigation\' );\r\nfunction _brgm_post_navigation() {\r\n	if ( is_singular( \'post\' ) ) {\r\n		echo \'<div class=\"brgm-post-nav\">\';\r\n			previous_post_link( \'%link\', \'<div class=\"prev\"><< Previous Blog</div>\' );\r\n			next_post_link( \'%link\',\'<div class=\"next\">Next Blog >></div>\');\r\n		echo \'</div>\';\r\n	}\r\n}\r\n\r\n// add read more after excerpt\r\nadd_filter(\'excerpt_more\', \'_brgm_readmore\');\r\nadd_filter( \'get_the_content_more_link\', \'_brgm_readmore\' );\r\nfunction _brgm_readmore() {\r\n	return \'<a class=\"more-link\" href=\"\' . get_permalink() . \'\">(read more..)</a>\';\r\n}\r\n\r\n//add featured image before title\r\nadd_action(\'genesis_entry_header\', \'_brgm_blog_archive_img\', 1);\r\nfunction _brgm_blog_archive_img() {\r\n    if ( is_single() ) return;\r\n    echo \'<div class=\"brgm-post-featured\">\'.get_the_post_thumbnail( get_the_ID(), \'full\' ). \'</div>\';\r\n}\r\n\r\n// Remove URL from comment form \r\nadd_filter(\'comment_form_default_fields\', \'_brgm_comment_form_fields\');\r\nfunction _brgm_comment_form_fields($fields) {\r\n  if( isset( $fields[\'url\'] ) ) unset( $fields[\'url\'] );\r\n    return $fields;\r\n}\r\n\r\nadd_shortcode(\'brgm-product-deal\', \'_brgm_deal\');\r\nfunction _brgm_deal( $atts=null ) {\r\n    $a = shortcode_atts( array(\r\n        \'id\' => \'\',\r\n    ), $atts );\r\n    $x = array( \'post_type\' => \'product\', \'posts_per_page\' => 1, \'product_cat\' => \'cheap-board-games\' );\r\n    $p = new WP_QUery( $x ); \r\n    $product = $p->get_posts(); \r\n    $id = ( isset( $product[0] ) ) ? $product[0]->ID : $a[\'id\'];\r\n    $prod = new WC_Product( $id );\r\n    if ( !$prod ) return false;\r\n    #echo \'<pre>\', print_r( $prod, 1), \'</pre>\';\r\n    $data = \'<div class=\"deal-prod\"><h3 class=\"deal-title\">\'. $prod->post->post_title.\'</h3>\';\r\n    $data .= $prod->is_on_sale() ? \'<span class=\"off\">\'.round( ( ( $prod->regular_price \r\n            - $prod->sale_price ) / $prod->regular_price ) * 100 ). \'% OFF</span>\': \'\';\r\n    $data .= $prod->get_image($size = \'medium\');\r\n    $data .= \'<p align=\"center\"><a class=\"btn orange\" href=\"\'.get_the_permalink($prod->id).\'\">GET THIS DEAL</a></p>\';\r\n    return $data.\'</div>\';\r\n}\r\n\r\n// Shortcode Loader\r\nfunction _brgm_shortcode() {\r\n    $code = array(\r\n        //\'points\' => \'<img class=\"manual-optin-trigger alignnone size-full wp-image-1672\" style=\"cursor:pointer;\" data-optin-slug=\"ilsf0knkt13qw00j\" src=\"/wp-content/uploads/2016/05/BGpoints-rightsidebox.png\" alt=\"BGpoints-rightsidebox\" width=\"173\" height=\"164\" />\',\r\n        \'weekly\' => \'<img class=\"manual-optin-trigger alignnone size-full wp-image-1673\" style=\"cursor:pointer;\" data-optin-slug=\"pv4ng1rmqzn3mmep\" src=\"/wp-content/uploads/2016/05/BGweekly-rightsidebox.png\" alt=\"BGweekly-rightsidebox\" width=\"186\" height=\"193\" />\',\r\n        \'recently-viewed\' => _brgm_recently_viewed(),\r\n        //\'product-deal\' => _brgm_deal(),\r\n    );\r\n    //Hide points if user is logged in\r\n    if(is_user_logged_in()){\r\n        $code[\'points\'] = \'\';\r\n    }\r\n    return $code;\r\n}\r\n\r\nfunction _brgm_load_shortcode() {\r\n    $codes = _brgm_shortcode();\r\n	foreach ($codes as $name => $output ) {\r\n		add_shortcode( \'brgm-\'.$name, function() use ( $output ){ return $output; });\r\n	}\r\n}\r\nadd_action(\'init\', \'_brgm_load_shortcode\');\r\n\r\nfunction _my_account_nav() {\r\n    wp_nav_menu( array(\r\n        \'menu\'              => \'Account Menu\',\r\n        \'container_class\'   => \'account-menu block\',\r\n    ));\r\n}\r\nadd_action(\'brgm/account/nav\', \'_my_account_nav\');\r\nadd_filter(\'woocommerce_my_account_my_address_title\', create_function( \'$a\', \'return;\' ) );\r\n\r\n//Replace text if user is logged in\r\n  add_filter(\'the_title\',\'show_loggedin_text\');\r\n  function show_loggedin_text($title) {\r\n    if (!is_admin() && $title == \'[AccountLink]\') {\r\n      if (is_user_logged_in()) {\r\n        $title = __(\'My Account\',\'dynatheme\');  \r\n      } else {\r\n        $title = __(\'Join BG!\',\'dynatheme\');  \r\n      }\r\n    }\r\n    return $title;\r\n  }\r\n\r\n// Account page additional data\r\nadd_action(\'brgm/accouont/section\', \'_brgm_accpage_prod\', 99);\r\nfunction _brgm_accpage_prod() {\r\n    echo do_shortcode(\'[cm cl=\"game-on-sale\"]<h3 class=\"bord\"><span class=\"a\">Games on Sale:</span></h3>[brgm_slider cat=\"discount-board-games\"][/cm][cm cl=\"featured-game\"]<h3 class=\"bord\"><span class=\"a\">Featured Games:</span></h3>[brgm_slider featured=\"yes\"]\r\n[/cm]\');\r\n}\r\n\r\nfunction _bgrgm_points_awards_reviews() {\r\n    if( is_plugin_active( \'bgpr/bgpr.php\' ) ) {\r\n    setlocale(LC_MONETARY, \'en_US\');\r\n    global $current_user;\r\n      	$current_user = wp_get_current_user();\r\n    $user_id = $current_user->ID;\r\n    $bg_points = get_user_meta( $user_id, \'bgpr_current_point_total\', true );\r\n    $earned_bucks = get_user_meta( $user_id, \'bg_earned_bucks\', true ); \r\n    /*$reviews = get_posts( array(\r\n        \'numberposts\' => -1,\r\n        \'meta_key\'    => \'_customer_user\',\r\n        \'meta_value\'  => $user_id,\r\n        \'post_type\'   => wc_get_order_types()));*/\r\n    $args = array (\'user_id\' => $user_id, \'post_type\' => \'product\');\r\n    $reviews = get_comments( $args );\r\n    if (empty($earned_bucks)):\r\n        $earned_bucks = 0.00;\r\n    endif;\r\n    if (empty($reviews)):\r\n        $reviewCount = \'0\';\r\n    else:\r\n        $reviewCount = count($reviews);\r\n    endif;\r\n    echo \'<div class=\"bg-account-data\">\';\r\n    echo \'<div class=\"one-third\"><b>My BG Points:</b><span class=\"points\">\'.$bg_points.\'</span></div>\';\r\n    echo \'<div class=\"one-third\"><b>My BG Bucks:</b><span class=\"bucks\">\'. number_format($earned_bucks, 2, \'.\', \' \').\'</span></div>\';\r\n    echo \'<div class=\"one-third last\"><b>My BG Reviews:</b><span class=\"reviews\">\'.$reviewCount.\'</span></div>\';\r\n    echo \'</div>\';\r\n    }\r\n}\r\nadd_action(\'brgm/account/data\', \'_bgrgm_points_awards_reviews\');\r\n\r\n/*\r\n* wc_remove_related_products\r\n*\r\n* Clear the query arguments for related products so none show.\r\n* Add this code to your theme functions.php file.\r\n*/\r\nfunction wc_remove_related_products( $args ) {\r\n  return array();\r\n}\r\n\r\nadd_filter(\'woocommerce_related_products_args\',\'wc_remove_related_products\', 10);\r\n\r\n\r\nfunction custom_discount($cart) {\r\n    global $woocommerce;\r\n \r\n    $woocommerce->cart->discount_total = 9;\r\n    \r\n}\r\n\r\n//Modify the archive/results pages on initial load to match the format\r\nfunction _bg_rate_this() {\r\n    global $post, $product;\r\n    $link = get_permalink( $post );\r\n    if($product->get_rating_html() === \'\'){\r\n        echo \'<div style=\"margin-top:-4px !important;\"><a href=\"\'.$link.\'#review_form\" class=\"rateGameText gimmeArrowsafter\" >Rate this game</a></div>\';\r\n    }\r\n}\r\n\r\n//CONTENT PAGES\r\n//\r\n//\r\n//Show current BG Bucks if user is logged in, else 0\r\nadd_shortcode(\'brgm_show_bucks_total\', \'_brgm_show_bucks_total\');\r\nfunction _brgm_show_bucks_total( $atts ){\r\n    if( is_plugin_active( \'bgpr/bgpr.php\' ) ) {\r\n        if(!is_user_logged_in()){\r\n            return \'0\';\r\n        }\r\n        else{\r\n            $user = wp_get_current_user();\r\n            $myBGBuck = get_user_meta($user->ID, \'bg_earned_bucks\',true); \r\n            return $myBGBuck;\r\n        }\r\n    }\r\n}\r\n\r\n//Show current BG Points if user is logged in, else 0\r\nadd_shortcode(\'brgm_show_points_total\', \'_brgm_show_points_total\');\r\nfunction _brgm_show_points_total( $atts ){\r\n    if(!is_user_logged_in()){\r\n        return \'0\';\r\n    }\r\n    else{\r\n        $user = wp_get_current_user();\r\n        $myBGPoints = get_user_meta($user->ID, \'bgpr_current_point_total\',true); \r\n        return $myBGPoints;\r\n    }\r\n\r\n}\r\n\r\n//Get BG Bucks Earned\r\n//Used currently for order success page\r\nfunction brgm_get_bucks_earned($items){\r\n    if( is_plugin_active( \'bgpr/bgpr.php\' ) ) {\r\n        global $wpdb;\r\n    \r\n        $order_items = $items;\r\n        $total_valid_items = 0;\r\n        $total_earned = 0;\r\n        foreach ($order_items as $anItem) {\r\n            //players club doesnt count\r\n            if($anItem[\'product_id\'] != 2244)\r\n            {\r\n                $total_valid_items += $anItem[\'qty\'];\r\n            }\r\n        }\r\n        //$num_cart_items = $order->get_item_count();\r\n        $type = $total_valid_items.\'_game_purchase\';\r\n    \r\n        //This will break if we add a 6 game reward tier\r\n        if ($total_valid_items > 5){\r\n                $type = \'5_game_purchase\';\r\n        }\r\n        //Now add any bucks not used when signing up for players club\r\n        if(isset($_SESSION[\"cart_reward_bucks_left\"])){\r\n            $total_earned += $_SESSION[\"cart_reward_bucks_left\"];\r\n        }\r\n        //echo \'type: \'.$type;\r\n        $result = $wpdb->get_row(\"SELECT * FROM {$wpdb->prefix}bg_bucks_rewards WHERE action_type = \'$type\' LIMIT 1\");\r\n        if($result){\r\n            $total_earned += $result->buck_reward;\r\n            return $total_earned;\r\n        }\r\n        return \'error\';\r\n    }\r\n}\r\n\r\n//CHECKOUT MODIFICATIONS\r\nadd_filter(\'woocommerce_create_account_default_checked\' , function ($checked){\r\n    if(!is_user_logged_in()){\r\n        return true;\r\n    }\r\n});\r\n\r\nadd_filter( \'woocommerce_ship_to_different_address_checked\', \'__return_false\' );\r\n\r\n//Filter images to display https always\r\nfunction convert_to_https( $original ) {\r\n    // use preg_replace() to replace http:// with https://\r\n    $output = preg_replace( \"^http:\", \"https:\", $original );\r\n    return $output;\r\n}\";s:20:\"admin-cmk-custom-php\";s:5345:\"<?php\r\n##Use this editor only if you need PHP admin functionality.\r\n//remove animate style\r\nadd_filter(\'cmk/minified/css\', \'custom_remove_css\');\r\nfunction custom_remove_css( $css ) {\r\n    unset( $css[\'animate\'] );\r\n    return $css;\r\n}\r\n// Add Navigation Extra Elements ( Requires to be fire on admin )\r\nadd_filter( \'wp_nav_menu_items\', \'brgm_nav_cart\', 10, 2 );\r\nfunction brgm_nav_cart( $menu, $args ) {\r\n	if ( \'primary\' !== $args->theme_location ) return $menu;\r\n    $menu .= \'<li class=\"right menu-cart\"><a class=\"cart-data\" href=\"/cart\" title=\"View your shopping cart\"><img src=\"/wp-content/uploads/2016/06/cart-icon.png\"> - \'.sprintf (_n( \'%d item\', \'%d items\', WC()->cart->get_cart_contents_count() ), WC()->cart->get_cart_contents_count() ).\' \'.WC()->cart->get_cart_total().\'</a><a class=\"checkoutl\" href=\"/checkout\">Checkout</a></li>\';\r\n	return $menu;\r\n}\r\n\r\n//Update Cart element Via Ajax\r\nfunction brgm_cart_ajax( $fragments ) {\r\n	$fragments[\'.cart-data\'] = \'<a class=\"cart-data\" href=\"/cart\" title=\"View your shopping cart\"><img src=\"/wp-content/uploads/2016/06/cart-icon.png\"> - \'.sprintf (_n( \'%d item\', \'%d items\', WC()->cart->get_cart_contents_count() ), WC()->cart->get_cart_contents_count() ).\' \'.WC()->cart->get_cart_total().\'</a>\';\r\n	return $fragments;\r\n}\r\nadd_filter( \'woocommerce_add_to_cart_fragments\', \'brgm_cart_ajax\' );\r\n\r\n//remove woocommerce category hierarchy\r\n#add_filter( \'woocommerce_taxonomy_args_product_cat\', \r\n#\'my_woocommerce_taxonomy_args_product_cat\' );\r\nfunction my_woocommerce_taxonomy_args_product_cat( $args ) {\r\n	$args[\'rewrite\'][\'hierarchical\'] = false;\r\n	return $args;\r\n}\r\n\r\n//add rewrite rule for /find slug\r\nadd_action( \'init\', \'_bgrm_rewrite\' );\r\nfunction _bgrm_rewrite() {\r\n    add_rewrite_rule( \'games/([^/]+)/?$\', \'index.php?s=$matches[1]&post_type=product\', \"top\" );\r\n    add_rewrite_rule( \'games/([^/]+)/page/([0-9]{1,})/?$\', \r\n        \'index.php?s=$matches[1]&post_type=product&paged=$matches[2]\', \"top\" \r\n    );\r\n}\r\n\r\nfunction _brgm_product_meta_tabs($tabs){\r\n    $tabs[\'brgm-video\'] = array(\r\n        \'label\'     => __( \'Video\', \'brgm\' ),\r\n        \'target\'    => \'brgm_video_wrap\',\r\n        \'class\'     => array(),\r\n    );\r\n    $tabs[\'brgm-witb\'] = array(\r\n        \'label\'     => __( \'Inside the Box\', \'brgm\' ),\r\n        \'target\'    => \'brgm_witb_wrap\',\r\n        \'class\'     => array(),\r\n    );\r\n    return($tabs);\r\n}\r\nadd_filter(\'woocommerce_product_data_tabs\', \'_brgm_product_meta_tabs\', 20, 1);\r\n\r\nadd_action( \'woocommerce_product_data_panels\', \'_brgm_product_video_tab\' );\r\nfunction _brgm_product_video_tab() {\r\n	global $woocommerce, $post;\r\n	echo \'<div id=\"brgm_video_wrap\" class=\"panel woocommerce_options_panel\">\';\r\n    woocommerce_wp_text_input( array( \r\n        \'id\'            => \'_brgm_video_sum\', \r\n        \'label\'         => __( \'Video Summary\', \'brgm\' ),\r\n        \'default\'  		=> \'0\',\r\n        \'desc_tip\'    	=> false,\r\n    ));\r\n    woocommerce_wp_text_input( array( \r\n        \'id\'            => \'_brgm_video_howto\', \r\n        \'label\'         => __( \'How to Play Video\', \'brgm\' ),\r\n        \'default\'  		=> \'0\',\r\n        \'desc_tip\'    	=> false,\r\n    ));\r\n    woocommerce_wp_text_input( array( \r\n        \'id\'            => \'_brgm_video_review\', \r\n        \'label\'         => __( \'Review\', \'brgm\' ),\r\n        \'default\'  		=> \'0\',\r\n        \'desc_tip\'    	=> false,\r\n    ));\r\n    woocommerce_wp_text_input( array( \r\n        \'id\'            => \'_brgm_video_gameplay\', \r\n        \'label\'         => __( \'Game Play Video\', \'brgm\' ),\r\n        \'default\'  		=> \'0\',\r\n        \'desc_tip\'    	=> false,\r\n    ));\r\n    echo \'</div>\';\r\n    echo \'<div id=\"brgm_witb_wrap\" class=\"panel woocommerce_options_panel\">\';\r\n    woocommerce_wp_textarea_input( array( \r\n        \'id\'            => \'_brgm_witb\', \r\n        \'label\'         => __( \'What\\\'s Inside the Box\', \'brgm\' ),\r\n        \'desc_tip\'    	=> false,\r\n    ));\r\n    echo \'</div>\';\r\n}\r\n\r\nadd_action(\'woocommerce_process_product_meta\', \'_brgm_process_meta_data\', 10, 2);\r\nfunction _brgm_process_meta_data( $id ) {\r\n    _brgm_update_meta($id, \'_brgm_video_sum\');\r\n    _brgm_update_meta($id, \'_brgm_video_howto\');\r\n    _brgm_update_meta($id, \'_brgm_video_review\');\r\n    _brgm_update_meta($id, \'_brgm_video_gameplay\');\r\n    _brgm_update_meta($id, \'_brgm_witb\');\r\n}\r\n\r\nfunction _brgm_update_meta( $id, $key ) {\r\n    $value = ( isset( $_POST[$key] ) ) ? $_POST[$key]  : false;\r\n    if ( $value ) update_post_meta( $id, $key, $value);\r\n}\r\n\r\nadd_action(\'wp_logout\',\'_brgm_redirecto_home\');\r\nfunction _brgm_redirecto_home(){\r\n    wp_safe_redirect( home_url() );\r\n    exit;\r\n}\r\n\r\nadd_action(\'woocommerce_edit_account_form_start\', \'_brgm_editacc_addfield\');\r\nfunction _brgm_editacc_addfield() {\r\n    $user = wp_get_current_user();\r\n    echo \'<p class=\"woocommerce-FormRow woocommerce-FormRow--wide form-row form-row-wide\">\r\n		<label for=\"display_name\">Display Name <span class=\"required\">*</span></label>\r\n		<input type=\"text\" class=\"woocommerce-Input woocommerce-Input--text input-text\" name=\"display_name\" id=\"display_name\" value=\"\'.$user->display_name.\'\" /></p>\';\r\n}\r\n\r\nadd_action( \'woocommerce_save_account_details\', \'_brgm_save_account_details\' );\r\nfunction _brgm_save_account_details( $id ) {\r\n    $data = array(\r\n        \'ID\'            => $id,\r\n        \'display_name\'  => wc_clean( $_POST[\'display_name\'] ),\r\n    );\r\n    wp_update_user( $data );\r\n}\";s:17:\"cmk-minify-script\";s:1:\"1\";s:17:\"cmk-custom-script\";s:6869:\"( function($) {\r\n    \r\n	$(\'.genesis-nav-menu\').cmknav({\r\n		label: \'<i class=\"fa fa-navicon\"></i> MENU\',\r\n		action: \'PushLeft\',\r\n		adToEl: \'.title-area\',\r\n		custom: true\r\n	});//This code is required for Mobile Menu\r\n	//Start your code below this line\r\n	$(\'.single.woocommerce .thumbnails1\').bind( \'mousewheel DOMMouseScroll\', function (e) {\r\n        var e0 = e.originalEvent,\r\n            delta = e0.wheelDelta || -e0.detail;\r\n    \r\n        this.scrollTop += ( delta < 0 ? 1 : -1 ) * 30;\r\