lass=\"time\"><span>\' + brgmw( (\'0\' + seconds).slice(-2) ) + \'</span> Seconds</p>\';\r\n        document.getElementById(\'countdown\').innerHTML = html;\r\n    }\r\n    \r\n    function brgmw( str ) {\r\n        var i = str.length;\r\n        var el = \'\';\r\n        for (var i = 0, len = str.length; i < len; i++) {\r\n          el += \'<i>\'+str[i]+\'</i>\';\r\n        }\r\n        return el;\r\n    }    \r\n    //brgm_deal_time();\r\n    timer = setInterval(brgm_deal_time, 1000);\r\n</script>'),(18862,1847,'_wp_page_template','default'),(18863,1847,'_edit_last','2'),(18864,1625,'_edit_lock','1470870303:2'),(18865,1848,'_menu_item_type','custom'),(18866,1848,'_menu_item_menu_item_parent','0'),(18867,1848,'_menu_item_object_id','1848'),(18868,1848,'_menu_item_object','custom'),(18869,1848,'_menu_item_target',''),(18870,1848,'_menu_item_classes','a:1:{i:0;s:0:\"\";}'),(18871,1848,'_menu_item_xfn',''),(18872,1848,'_menu_item_url','#my-account'),(18874,1849,'_menu_item_type','custom'),(18875,1849,'_menu_item_menu_item_parent','0'),(18876,1849,'_menu_item_object_id','1849'),(18877,1849,'_menu_item_object','custom'),(18878,1849,'_menu_item_target',''),(18879,1849,'_menu_item_classes','a:1:{i:0;s:0:\"\";}'),(18880,1849,'_menu_item_xfn',''),(18881,1849,'_menu_item_url','#games-i-want'),(18883,1850,'_menu_item_type','custom'),(18884,1850,'_menu_item_menu_item_parent','0'),(18885,1850,'_menu_item_object_id','1850'),(18886,1850,'_menu_item_object','custom'),(18887,1850,'_menu_item_target',''),(18888,1850,'_menu_item_classes','a:1:{i:0;s:0:\"\";}'),(18889,1850,'_menu_item_xfn',''),(18890,1850,'_menu_item_url','#games-i-love'),(18892,1851,'_menu_item_type','custom'),(18893,1851,'_menu_item_menu_item_parent','0'),(18894,1851,'_menu_item_object_id','1851'),(18895,1851,'_menu_item_object','custom'),(18896,1851,'_menu_item_target',''),(18897,1851,'_menu_item_classes','a:1:{i:0;s:0:\"\";}'),(18898,1851,'_menu_item_xfn',''),(18899,1851,'_menu_item_url','#games-i-own'),(18919,185